import sys

def main():
    s = sys.stdin.readline()
    nums = []
    ops = []
    prec = {'+': 1, '-': 1, '*': 2, '/': 2}

    def apply():
        op = ops.pop()
        b = nums.pop()
        a = nums.pop()
        if op == '+':
            nums.append(a + b)
        elif op == '-':
            nums.append(a - b)
        elif op == '*':
            nums.append(a * b)
        else:
            q = abs(a) // abs(b)
            nums.append(q if (a < 0) == (b < 0) else -q)

    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c.isdigit():
            j = i
            while j < n and s[j].isdigit():
                j += 1
            nums.append(int(s[i:j]))
            i = j
            continue
        if c == '(':
            ops.append(c)
        elif c == ')':
            while ops[-1] != '(':
                apply()
            ops.pop()
        elif c in prec:
            while ops and ops[-1] != '(' and prec[ops[-1]] >= prec[c]:
                apply()
            ops.append(c)
        i += 1
    while ops:
        apply()
    print(nums[0])

main()

