        pos += 1
        r = term()
        v = v + r if op == '+' else v - r
    return v

def term():
    global pos
    v = factor()
    while peek() == '*' or peek() == '/':
        op = s[pos]
        pos += 1
        r = factor()
        v = v * r if op == '*' else div(v, r)
